import{_ as t,o as r,c as i,ah as s}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse(`{"title":"March 10: Schmid Incriminates Wöginger – The 'Hard Prose' Crumbles","description":"Thomas Schmid, the key witness, testifies against August Wöginger. A dramatic turning point for our mockumentary and the 'Horten Mystery'.","frontmatter":{"title":"March 10: Schmid Incriminates Wöginger – The 'Hard Prose' Crumbles","description":"Thomas Schmid, the key witness, testifies against August Wöginger. A dramatic turning point for our mockumentary and the 'Horten Mystery'.","date":"2026-03-10T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-10-schmid-belastet-woeginger.md","filePath":"en/logbuch/2026-03-10-schmid-belastet-woeginger.md"}`),a={name:"en/logbuch/2026-03-10-schmid-belastet-woeginger.md"};function o(n,e,h,l,c,m){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="⚖️-march-10-schmid-incriminates-woginger-–-the-„hard-prose-crumbles" tabindex="-1">⚖️ March 10: Schmid Incriminates Wöginger – The „Hard Prose“ Crumbles <a class="header-anchor" href="#⚖️-march-10-schmid-incriminates-woginger-–-the-„hard-prose-crumbles" aria-label="Permalink to &quot;⚖️ March 10: Schmid Incriminates Wöginger – The „Hard Prose“ Crumbles&quot;">​</a></h1><p>It is <strong>Tuesday, 2:49 PM</strong>. While the sun shines over Linz, dark clouds are gathering over August Wöginger&#39;s defense strategy at the Regional Court. Today marks perhaps the most important turning point in <strong>Part 4: The Political Love Story</strong>.</p><h3 id="the-key-witness-breaks-the-silence" tabindex="-1"><strong>The Key Witness Breaks the Silence</strong> <a class="header-anchor" href="#the-key-witness-breaks-the-silence" aria-label="Permalink to &quot;**The Key Witness Breaks the Silence**&quot;">​</a></h3><p><strong>Thomas Schmid</strong>, the former „Shadow Chancellor“ of the Ministry of Finance, laid his cards on the table in his testimony today. His statements are pure dynamite for the narrative of the „citizen&#39;s request“:</p><ul><li><strong>The Explicit Request:</strong> Schmid stated that Wöginger personally and directly asked him to intervene on behalf of the ÖVP mayor Michael L.</li><li><strong>No Technical Review:</strong> Qualification was „never an issue.“ It was solely about „complying with Wöginger&#39;s request.“</li><li><strong>The Chats of Power:</strong> „We made it 😃) The mayor owes you one!“ – This message from Schmid to Wöginger echoes through the courtroom today.</li></ul><h3 id="analysis-the-pointillism-of-favors" tabindex="-1"><strong>Analysis: The Pointillism of Favors</strong> <a class="header-anchor" href="#analysis-the-pointillism-of-favors" aria-label="Permalink to &quot;**Analysis: The Pointillism of Favors**&quot;">​</a></h3><p>For our mockumentary, this is the confirmation of the <strong>„Pointillism of Money“</strong>. Every chat, every SMS is a small point that may seem harmless on its own („citizen&#39;s request“), but in the overall picture results in a monumental painting of cronyism.</p><blockquote><p><em>„It&#39;s like a mosaic of power. You have to step back far enough to see the abyss.“</em> — Oliver Masucci (as Thomas Schmid), draft for Scene 88.</p></blockquote><h3 id="woginger-s-defense-under-pressure" tabindex="-1"><strong>Wöginger&#39;s Defense Under Pressure</strong> <a class="header-anchor" href="#woginger-s-defense-under-pressure" aria-label="Permalink to &quot;**Wöginger&#39;s Defense Under Pressure**&quot;">​</a></h3><p>Wöginger sticks to his line: He did nothing wrong, it was all just „regional politics.“ But Schmid&#39;s cool precision puts the ÖVP&#39;s „Hard Prose“ under massive pressure. Wöginger&#39;s apology, that he was „sorry for what his request triggered,“ seems like a weak protective wall against the flood of evidence in this context.</p><h3 id="what-this-means-for-the-film" tabindex="-1"><strong>What This Means for the Film:</strong> <a class="header-anchor" href="#what-this-means-for-the-film" aria-label="Permalink to &quot;**What This Means for the Film:**&quot;">​</a></h3><p>Today we collected exclusive material for the final montage of Part 4. The juxtaposition of Wöginger&#39;s „citizen&#39;s request“ rhetoric and Schmid&#39;s „wish fulfillment“ statement will form the emotional center of the finale.</p><ul><li><strong>Theft of Time:</strong> We are staging this trial as the moment when time runs out for the old system.</li><li><strong>April 21:</strong> The date of the verdict is now our fixed point. Until then, we will continue to deconstruct the „Hard Prose.“</li></ul><h3 id="🛑-update-the-roadmap-to-the-verdict" tabindex="-1">🛑 UPDATE: The Roadmap to the Verdict <a class="header-anchor" href="#🛑-update-the-roadmap-to-the-verdict" aria-label="Permalink to &quot;🛑 UPDATE: The Roadmap to the Verdict&quot;">​</a></h3><ul><li><strong>Verdict Announcement:</strong> Expected for <strong>April 21, 2026</strong>.</li><li><strong>Next Steps:</strong> We are preparing a special episode of our logbook podcast in which we contrast the statements of Schmid and Scharf.</li></ul><hr><p><strong>„A tax office is not a calculator? Maybe. But justice is an exact science.“</strong></p><p>👉 <a href="/en/recherche/thomas-schmid-chats-details.html">Analyze the Schmid chats in detail</a> 👉 <a href="/en/logbuch/2026-03-01-system-schluckauf-und-verschleierung.html">To the current status of the &#39;Market Correction&#39;</a></p><hr><p><em>Reporting from March 10, 2026, 2:49 PM. The mockumentary is almost writing itself.</em></p>',20)])])}const u=t(a,[["render",o]]);export{g as __pageData,u as default};
